import json, subprocess
def run(cases, events=None, timeout=10):
    d = {"seed":"s","definitions":[],"timeout_ms":timeout,"cases":cases,"events":events or [],"channels":[]}
    p = subprocess.run(['python3','-B','main.py'], input=json.dumps(d).encode(), capture_output=True, cwd='/workspace/project')
    return json.loads(p.stdout.decode())
def C(name, frames):
    return {"name":name,"frames":frames,"expect":{"method":"GET","target":"/","host":"h"}}
def H(end=None, pairs=None):
    f = {"Type":"headers","data_to_transfered":pairs or [["a","b"]]}
    if end is not None: f["End_Stream"] = end
    return f
def D(data="x", end=None):
    f = {"Type":"data","data_to_transfered":data}
    if end is not None: f["End_Stream"] = end
    return f
def G(data="g", end=None):
    f = {"Type":"datagram","data_to_transfered":data}
    if end is not None: f["End_Stream"] = end
    return f
F=[]
def show(name, out, want):
    got = [(c['state'],c['at'],c['frames'],c['request_frames']) for c in out['cases']]
    if got != want: F.append(name); print('FAIL',name,got,want)
    else: print('PASS',name)
