show('datagram default end ignored', run([C('a',[G(),D()])], [{"at":5,"kind":"headers","stream":0,"fields":[],"end":True}]), [('ok',5,2,1)])
show('datagram then datagram', run([C('a',[G(),G()])], [{"at":5,"kind":"headers","stream":0,"fields":[],"end":True}]), [('ok',5,2,0)])
